      '6': 'Máy tránh đổi Xe, bình sang g6: dọa ăn Tốt g5 đang không có quân bảo vệ và nhắm Mã g7.',
      '6...': 'Pháo lui về i8: từ đây Pháo có thể bình sang g8, qua ngòi Mã g7 đuổi Xe g6.',
