      '8': 'Xe lui ăn Tốt g5 – máy hơn một Tốt; Xe vẫn nhắm Mã g7 (có Mã e8 bảo vệ).',
      '8...': 'Phi Tượng lên e7, dọa ăn Xe g5 đang không có quân bảo vệ.',
