      '11': 'Xe ăn Tốt c6 – vừa thoát khỏi Mã f5, vừa dọa ăn Mã c7 đang không có quân bảo vệ. Máy đã hơn hai Tốt.',
      '11...': 'Pháo tiến lại i7: qua ngòi Tượng e7, Pháo bảo vệ Mã c7. Theo lời bình trong nguồn, tới đây hai bên vẫn đi theo sách.',
      '12': 'Tiến Tốt 3 lên g4. Lời bình trong nguồn cho rằng nước thường gặp là 12. M8.7 – máy chọn con đường riêng.',
      '13': 'Tốt vượt sông lên g5, dọa ăn Mã f5 đang không có quân bảo vệ.',
      '13...':
        'Mã f5 nhảy vào d4: dọa ăn Xe c6 (không có quân bảo vệ) và nhắm Pháo e2. Nguồn kể rằng Hứa Ngân Xuyên đã suy nghĩ rất lâu trước nước này.',
      '14': 'Xe né sang b6, dọa ăn Pháo b7 đang không có quân bảo vệ.',
      '14...':
        'Pháo lui về b9. Lời bình trong nguồn khen nước này: nếu vội dùng Tượng ăn Tốt (14...T5.7) thì Đỏ đáp 15. B7.1 và thế trận Đen khó phối hợp – máy tính cũng đánh giá khi đó Đỏ khá hơn rõ.',
      '15': 'Mã trái lên c2, dọa ăn Mã d4 đang không có quân bảo vệ.',
      '15...': 'Mã d4 lui về f3, cùng Tượng e7 nhắm Tốt qua sông g5.',
      '16...':
        'Mã ăn Tốt g5. Sau vòng di chuyển d4 – f3 – g5, Mã Đen diệt được Tốt qua sông và đứng ở ô vừa công vừa thủ (bảo vệ Tốt e6, Tốt i6).',
      '17...': 'Pháo b9 bình sang d9: qua ngòi Mã d4, Pháo dọa ăn Pháo d2 đang không có quân bảo vệ.',
      '18': 'Mã d4 nhảy lên f5 – rút ngòi để Pháo d9 không bắn được Pháo d2, đồng thời nhắm Tượng e7.',
      '20': 'Tốt c4 vượt sông lên c5, có Xe c1 đứng sau yểm trợ.',
      '20...': 'Mã g5 nhảy lên h3, mở hàng 5 để Xe h5 nhắm Mã f5 đang không có quân bảo vệ.',
      '21': 'Mã g2 lên h4 bảo vệ Mã f5.',
      '21...':
        '**Chiến lược đơn giản hóa**: Pháo i7 bình sang h7, qua ngòi Xe h5 nhắm Mã h4, mở màn chuỗi đổi quân. Lời bình trong nguồn cho rằng với quân Đen, kết quả này đã đáng hài lòng; đường khác là 21...T5.3 ăn Tốt c5, phức tạp và khó lường hơn nhiều.',
