      '24': 'Pháo d2 bị hai quân nhắm nên đổi luôn: Pháo ăn Pháo d9 (Xe d8 làm ngòi).',
      '24...': 'Mã c7 lui ăn lại Pháo (đồng thời tránh Tốt c6). Sau chuỗi đổi quân, Đen hết Pháo, còn hai Mã; Đỏ còn một Mã, một Pháo.',
