    difficulty: 5,
    context:
      'Cúp Hàn Tín (淮阴·韩信杯) ở Hoài An, Giang Tô quy tụ sáu kỳ thủ Trung Quốc đại lục và sáu danh thủ quốc tế. Lần thứ 2 diễn ra từ 27 đến 30/5/2010; hai kỳ thủ Việt Nam Nguyễn Thành Bảo và Lại Lý Huynh được mời nhờ lọt vào tốp đầu giải vô địch thế giới 2009. Nguyễn Thành Bảo (sinh 1978, Nam Định) – nhà vô địch trẻ châu Á 1998 và vô địch quốc gia Việt Nam 2007 – mở màn không suôn sẻ khi thua chính đồng đội Lại Lý Huynh ở vòng 1. Ở vòng 4 (ngày 28/5), anh cầm quân Đỏ gặp Lữ Khâm – năm lần vô địch toàn quốc Trung Quốc, hai lần vô địch thế giới – và có một trong những chiến thắng đáng nhớ nhất của cờ tướng Việt Nam. Vài tháng sau, tại Asiad 2010 ở Quảng Châu, Nguyễn Thành Bảo giành huy chương bạc nội dung cá nhân nam, xếp trên chính Lữ Khâm (huy chương đồng).',
    summary:
      'Nguyễn Thành Bảo mở cuộc bằng Tiên nhân chỉ lộ rồi chuyển sang Pháo đầu. Ở trung cuộc, anh khéo đưa Tốt 7 qua sông để giữ Pháo, rồi dùng Pháo và Mã ăn liền ba Tốt, hơn Đen một Tốt. Sau một loạt nước lặp lại, Lữ Khâm đi sai ở nước 37: Xe Đỏ xuống chiếu, rồi lui về chiếu phát hiện bằng Pháo đáy và bắt Xe g5 – sau màn đổi Xe, Đỏ hơn hai Tốt. Phần còn lại là một tàn cuộc kỹ thuật: Xe h3 trói chặt Xe, Pháo, Mã của Đen (cảnh mà trang nguồn gọi là "một Xe kìm ba quân"), trong khi các Tốt Đỏ lần lượt tiến lên. Lữ Khâm đầu hàng ở nước 76.',
