      '35...': 'Lên Sĩ e8 để bảo vệ Sĩ d9 đang bị Xe d6 dọa ăn; nhưng Sĩ rời f9 khiến Pháo a9 (qua ngòi Sĩ d9) nhắm được Tượng g9.',
