      'Rút ngòi của chính mình (20...P3-1) có thể vô tình mở đường chiếu cho đối phương.',
      'Theo luật cờ tướng, không được chiếu dai: bên chiếu liên tục làm lặp thế cờ sẽ bị xử thua, nên Đen buộc phải đổi nước (34...X6/3).',
      'Tướng của mình có thể yểm trợ Xe tấn công nhờ luật lộ mặt Tướng (29...X7-6 nhắm f0).',
