      'Cuối năm 2012, giải mời các nhà vô địch toàn quốc Cúp Bích Quế Viên (碧桂园杯) lần đầu được tổ chức tại Quảng Châu; giải về sau kéo dài mười lần và được giới cờ ví là "giải Oscar của làng cờ". Ở vòng 1 (ngày 16/12/2012), hai huyền thoại của thập niên 1980 gặp lại nhau: Liễu Đại Hoa (Hồ Bắc), người chấm dứt chuỗi mười lần vô địch liên tiếp của Hồ Vinh Hoa khi đăng quang các năm 1980 và 1981, và Lý Lai Quần (Hà Bắc), bốn lần vô địch toàn quốc (1982, 1984, 1987, 1991). Từ năm 1996, Lý Lai Quần chuyển sang kinh doanh bất động sản và dần rời xa thi đấu đỉnh cao – nhưng tay cờ của ông vẫn còn rất sắc.',
    summary:
      'Liễu Đại Hoa khai cuộc chậm rãi với Mã biên, rồi đi sai một nước Tốt ở nước 8: Pháo Đen lập tức quét ngang hàng 3, ăn Tốt i3 và dọa Xe. Sau màn đổi Xe, Đen hơn một Tốt. Đến nước 13, Lý Lai Quần tung một nước Tốt hai mục đích: vừa dọa ăn Tốt, vừa mở đường cho Mã đuổi Xe – và ngay sau đó Pháo Đen ăn Tốt g5, chỗ dựa duy nhất của Pháo g6. Hơn một Pháo, Đen chơi gọn gàng: chèn chân Mã, mời đổi Xe, dồn quân vào trung lộ. Sau 25 nước, Liễu Đại Hoa đầu hàng.',
    moves:
      '1. P8-5 M2.3 2. M8.7 X1-2 3. X9-8 P8-5 4. B3.1 M8.7 5. P2-3 X9-8 6. M2.1 P2.4 7. S6.5 M7/5 8. B7.1 P2-9 9. X8.9 P9.3 10. X8/4 X8.9 11. P3.4 P5-7 12. S5.4 X8/6 13. B3.1 B3.1 14. X8/1 P7.2 15. B7.1 X8-7 16. M1.2 P7-8 17. M2/3 X7.1 18. X8-1 X7-3 19. M7/5 M5.6 20. M3.4 X3.1 21. T7.9 X3-4 22. M5.7 B9.1 23. X1-2 X4.2 24. M7/8 P8-5 25. S4/5 X4/2',
