      'Nguyễn Hoàng Yến khai cuộc mạnh mẽ: Mã nhảy vào ăn Tốt đầu, Pháo đầu ăn lại Mã kèm chiếu. Đường Đan đáp bằng cách đổi Pháo, đưa Xe xuống hàng 3 ăn Tốt, rồi đổi Xe để bước vào trung tàn Xe – Pháo – Mã cân bằng về quân nhưng quân Đen hoạt động hơn hẳn. Khi Mã Đỏ chạy ra biên (36. M3.1), Đen lên Sĩ phòng thủ, và chỉ hai nước sau Pháo Đen lùi về e6 bắt đôi Xe b6 và Pháo d4.',
