      '32': 'Xe b4 lao lên b9 chiếu Tướng theo hàng đáy (c9, d9 đều trống); sau khi Đen dùng Sĩ e8 lui về d9 cản, Mã d6 mất quân bảo vệ.',
      '33': 'Xe b9 lui về b6, bắt đôi Tốt a6 và Mã d6 – cả hai đều không có quân bảo vệ.',
