      '34...': 'Tốt c5 vượt sông xuống c4, dọa ăn Mã c3 không có quân bảo vệ; Tốt c4 lại được Pháo c2 (qua ngòi Mã c3) bảo vệ.',
      '35...': 'Mã e8 nhảy lên c7, dọa ăn Xe a6 (không có quân bảo vệ), đồng thời bảo vệ Tốt e6 và Sĩ d9.',
