      '44': 'Pháo c9 lui về c8 chiếu tiếp (Sĩ e8 làm ngòi); Đỏ dùng các nước chiếu để tìm cơ hội trong khi Mã b6 vẫn bị Xe b5 nhắm.',
      '45': 'Pháo c8 tiến lên c9 chiếu tiếp qua ngòi Sĩ d9; sau khi Tướng Đen lên lại f8, thế cờ lặp lại đúng như sau nước 43...',
      '46': 'Pháo c9 lui một mạch về c2 ăn Tốt c2 – Tốt Đen đã tiến sát cung Tướng Đỏ.',
      '46...': 'Pháo f0 rút lên f6: qua ngòi Tốt e6, Pháo dọa bắn Xe d6.',
      '47': 'Mã b6 (đang bị Xe b5 nhắm) nhảy vào d7 chiếu Tướng – thí Mã: nếu Sĩ e8 ăn Mã, Sĩ đứng ở d7 sẽ cản chân Mã c7, khiến Tốt e6 mất quân bảo vệ.',
      '47...': 'Sĩ e8 ăn Mã d7, Đen hơn hẳn về quân; nhưng Sĩ ở d7 cản chân Mã c7 nên Tốt e6 không còn được bảo vệ.',
      '48': 'Xe d6 ăn Tốt e6 (Tốt đã mất quân bảo vệ), thoát khỏi đòn Pháo f6 và quay sang dọa ăn chính Pháo này.',
