      '50...': 'Đen bình tĩnh tiến Tốt biên, chấp nhận trả lại Mã – vì đã tính sẵn đòn Pháo.',
      '51': 'Pháo c2 ăn Mã c7 qua ngòi Xe c6; từ c7, qua ngòi Sĩ d7, Pháo còn nhắm Pháo f7.',
