      '52...':
        'Pháo f7 bắn Pháo c7 (Sĩ d7 làm ngòi). Đen còn Xe, Pháo, Tốt và hai Sĩ, Đỏ chỉ còn Xe, một Tượng và một Tốt. Doãn Thăng đầu hàng – Lại Lý Huynh vô địch thế giới.',
